WITH recent_products AS (SELECT * FROM products WHERE category IN ('Home', 'Sports', 'Grocery') AND price <= 1190), ProductsStats AS (SELECT CASE WHEN stock_qty >= 433 THEN 'high' WHEN stock_qty >= 196 THEN 'mid' ELSE 'low' END AS stock_qty_bucket, ROUND((100 * SUM(CASE WHEN brand = 'Acme' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_acme FROM recent_products GROUP BY CASE WHEN stock_qty >= 433 THEN 'high' WHEN stock_qty >= 196 THEN 'mid' ELSE 'low' END) SELECT stock_qty_bucket, pct_acme FROM ProductsStats WHERE pct_acme >= 27 ORDER BY stock_qty_bucket DESC, pct_acme
